// of the bridge. deleteOnTimeout(5) - this entry is currently in use and
// will remain so until it is aged out.
var Dot1dStaticStatus = snmp.NewColumn[Dot1dStaticStatusValue](snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1, 4), snmp.KindInteger32, func(vb snmp.VarBind) (Dot1dStaticStatusValue, error) {
	v, err := snmp.DecodeInt32(vb)
	if err != nil {
		return Dot1dStaticStatusValue(0), err
	}
	return Dot1dStaticStatusValue(v), nil
})

// Dot1dStaticTableRow is one row of dot1dStaticTable. Index carries the OID
// suffix beyond the table-entry prefix; the remaining fields are
// populated only for columns the caller passed to Walk().
type Dot1dStaticTableRow struct {
	Index                    snmp.OID
	Dot1dStaticAddress       net.HardwareAddr
	Dot1dStaticReceivePort   int32
	Dot1dStaticAllowedToGoTo []byte
	Dot1dStaticStatus        Dot1dStaticStatusValue
}

// Dot1dStaticTableWalker is a table-aware walker over dot1dStaticTable.
// Construct via Dot1dStaticTable.Walk(ctx, sess, cols...).
type Dot1dStaticTableWalker struct {
	rw    *snmp.RawWalker
	cols  []snmp.AnyColumn
	byCol map[uint32]snmp.AnyColumn
}

// Iter yields one (Index, Row) pair per row of the table walk. The
// full BulkWalk is buffered before any row is yielded, so the
// generated walker is correct over both column-major and row-major
// agent emission. Contracts:
//
//  1. Ordering: rows yield in the index's first-appearance position
//     in the agent's BulkWalk response — which for a well-behaved
//     agent equals lexicographic OID order over the index suffix.
//     This is NOT numerical order for composite-index tables
//     (e.g. ipAddrTable indexed by IP-as-OID: 192.168.0.10 sorts
//     before 192.168.0.2). Integer-keyed tables (ifTable,
//     hrProcessorTable) get numeric order for free.
//
//  2. Row presence: every index observed under the entry prefix
//     yields a row, even when only unrequested columns landed on
//     that index. The row's requested-column fields stay at zero.
//
//  3. Decode error: rows for indexes strictly before the failing
//     index in appearance order flush before Walker.Fail is set,
//     preserving partial-progress visibility for the operator.
//     The failing row and anything after it are not yielded.
//     Check Err() afterwards for the terminal cause.
//
//  4. Memory profile: O(rows × requested columns) buffered before
//     the first yield. Bounded by table size, not walk position —
//     callers that broke out early via 'for row := range Iter()'
//     still pay the full-walk buffer cost.
func (tw *Dot1dStaticTableWalker) Iter() iter.Seq2[snmp.OID, Dot1dStaticTableRow] {
	return func(yield func(snmp.OID, Dot1dStaticTableRow) bool) {
		entryWire := snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1).WireBytes()
		buffer := make(map[string]*Dot1dStaticTableRow)
		var orderIdx []snmp.OID
		var orderKey []string

		for rv := range tw.rw.Iter() {
			if !bytes.HasPrefix(rv.OID, entryWire) {
				continue
			}
			suffix := rv.OID[len(entryWire):]
			colID, colLen, okArc := snmp.RawFirstArc(suffix)
			if !okArc || colLen >= len(suffix) {
				continue
			}
			idxWire := suffix[colLen:]
			row, exists := buffer[string(idxWire)]
			if !exists {
				idx, idxErr := snmp.DecodeIndexArcs(idxWire)
				if idxErr != nil {
					continue
				}
				key := string(idxWire)
				row = &Dot1dStaticTableRow{}
				buffer[key] = row
				orderIdx = append(orderIdx, idx)
				orderKey = append(orderKey, key)
			}
			_, ok := tw.byCol[colID]
			if !ok {
				continue
			}
			var derr error
			switch colID {
			case 1:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := Dot1dStaticAddress.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.Dot1dStaticAddress = dv
					}
				}
			case 2:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.Dot1dStaticReceivePort = int32(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := Dot1dStaticReceivePort.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.Dot1dStaticReceivePort = dv
						}
					}
				}
			case 3:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := Dot1dStaticAllowedToGoTo.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.Dot1dStaticAllowedToGoTo = dv
					}
				}
			case 4:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.Dot1dStaticStatus = Dot1dStaticStatusValue(v)
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := Dot1dStaticStatus.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.Dot1dStaticStatus = dv
						}
					}
				}
			}
			if derr != nil {
				for i := 0; i < len(orderKey); i++ {
					if orderKey[i] == string(idxWire) {
						break
					}
					if !yield(orderIdx[i], *buffer[orderKey[i]]) {
						tw.rw.Fail(derr)
						return
					}
				}
				tw.rw.Fail(derr)
				return
			}
		}

		for i := 0; i < len(orderIdx); i++ {
			if !yield(orderIdx[i], *buffer[orderKey[i]]) {
				return
			}
		}
	}
}

// Err returns the underlying walker's terminal error, or nil if
// the walk completed naturally.
func (tw *Dot1dStaticTableWalker) Err() error {
	return tw.rw.Err()
}

// dot1dStaticTableT is the singleton type of Dot1dStaticTable.
type dot1dStaticTableT struct{}

// Dot1dStaticTable is the descriptor for the dot1dStaticTable table.
var Dot1dStaticTable dot1dStaticTableT

// Walk launches a BulkWalk over dot1dStaticTable and returns a
// table-aware iterator. Only the columns listed in cols are
// decoded; varbinds for unlisted columns are skipped. The walk
// rides the raw fast path (BulkWalkRaw); sessions or responses
// that cannot deliver raw bytes degrade transparently to the
// generic per-varbind decode.
func (dot1dStaticTableT) Walk(ctx context.Context, sess snmp.Session, cols ...snmp.AnyColumn) *Dot1dStaticTableWalker {
	w := sess.BulkWalkRaw(ctx, snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1))
	byCol := make(map[uint32]snmp.AnyColumn, len(cols))

	for _, c := range cols {
		o := c.OID()
		if o.Len() == 0 {
			continue
		}
		byCol[o.At(o.Len()-1)] = c
	}

	return &Dot1dStaticTableWalker{
		byCol: byCol,
		cols:  cols,
		rw:    w,
	}
}

// bRIDGEMIBOIDDispatch maps column wire keys ([snmp.OID.WireKey]) to their
// typed AnyColumn for fast
// lookup during table-walk decoding. Per-MIB-module — no global
// registry; cross-package callers should consult OIDDispatch().
var bRIDGEMIBOIDDispatch = map[string]snmp.AnyColumn{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 1, 4, 1, 1).WireKey():   Dot1dBasePort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 1, 4, 1, 2).WireKey():   Dot1dBasePortIfIndex,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 1, 4, 1, 3).WireKey():   Dot1dBasePortCircuit,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 1, 4, 1, 4).WireKey():   Dot1dBasePortDelayExceededDiscards,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 1, 4, 1, 5).WireKey():   Dot1dBasePortMtuExceededDiscards,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 1).WireKey():  Dot1dStpPort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 10).WireKey(): Dot1dStpPortForwardTransitions,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 11).WireKey(): Dot1dStpPortPathCost32,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 2).WireKey():  Dot1dStpPortPriority,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 3).WireKey():  Dot1dStpPortState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 4).WireKey():  Dot1dStpPortEnable,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 5).WireKey():  Dot1dStpPortPathCost,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 6).WireKey():  Dot1dStpPortDesignatedRoot,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 7).WireKey():  Dot1dStpPortDesignatedCost,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 8).WireKey():  Dot1dStpPortDesignatedBridge,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 2, 15, 1, 9).WireKey():  Dot1dStpPortDesignatedPort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 3, 1, 1).WireKey():   Dot1dTpFdbAddress,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 3, 1, 2).WireKey():   Dot1dTpFdbPort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 3, 1, 3).WireKey():   Dot1dTpFdbStatus,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 4, 1, 1).WireKey():   Dot1dTpPort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 4, 1, 2).WireKey():   Dot1dTpPortMaxInfo,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 4, 1, 3).WireKey():   Dot1dTpPortInFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 4, 1, 4).WireKey():   Dot1dTpPortOutFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 4, 1, 5).WireKey():   Dot1dTpPortInDiscards,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1, 1).WireKey():   Dot1dStaticAddress,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1, 2).WireKey():   Dot1dStaticReceivePort,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1, 3).WireKey():   Dot1dStaticAllowedToGoTo,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 5, 1, 1, 4).WireKey():   Dot1dStaticStatus,
}

// OIDDispatch returns a shallow copy of the package's wire-key →
// AnyColumn map. The copy isolates callers from accidental mutation
// of the package-internal map (#12).
func OIDDispatch() map[string]snmp.AnyColumn {
	out := make(map[string]snmp.AnyColumn, len(bRIDGEMIBOIDDispatch))
	for k, v := range bRIDGEMIBOIDDispatch {
		out[k] = v
	}
	return out
}
